import { useEffect, useMemo, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { useDynamicTitle } from '@/hooks/useDynamicTitle';
import { Mail, Archive, Send, Star, Trash2, Bell, Inbox, User, Clock, Search, X, Reply } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { OpenAPI, MessagesService } from '@/api';
import { request as __request } from '@/api/core/request';
import { toast } from 'sonner';
import { TabBar } from './components/TabBar';
import { SearchBar } from './components/SearchBar';
import { MessageList } from './components/MessageList';
import { MessageDetail } from './components/MessageDetail';
import { ComposeForm } from './components/ComposeForm';
import { ThreadsView } from './components/ThreadsView';
import { unwrapResponse, extractErrorMessage } from './utils/utils';
import { ALLOWED_TABS } from './constants/constants';
import type { IMessage, INotification, IThreadSummary, Message, MessageType } from './types/types';

/**
 * MessagesPage 容器组件
 * - 职责：集中管理页面状态与业务逻辑，向子组件下发纯数据与回调函数
 * - 目标：保持原有 UI，不改动路由，对外导出同名组件以确保引用路径稳定
 */
export function MessagesPage() {
  useDynamicTitle('消息');
  const [searchParams, setSearchParams] = useSearchParams();

  /** 初始化 Tab：从 URL 中读取并校验 */
  const initialTabRaw = (searchParams.get('tab') || 'inbox') as string;
  const initialTab = (ALLOWED_TABS.includes(initialTabRaw as MessageType) ? initialTabRaw : 'inbox') as MessageType;
  const [activeTab, setActiveTab] = useState<MessageType>(initialTab);

  /** 页面级状态 */
  const [selectedMessage, setSelectedMessage] = useState<Message | null>(null);
  const [showCompose, setShowCompose] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [debouncedQuery, setDebouncedQuery] = useState('');

  /** 各 Tab 的分页与过滤状态 */
  const [notificationsPage, setNotificationsPage] = useState(1);
  const [notificationsLimit, setNotificationsLimit] = useState(20);

  const [inboxPage, setInboxPage] = useState(1);
  const [inboxLimit, setInboxLimit] = useState(20);
  const [inboxOnlyUnread, setInboxOnlyUnread] = useState<boolean>(false);
  const [inboxOnlyFavorites, setInboxOnlyFavorites] = useState<boolean>(false);

  const [outboxPage, setOutboxPage] = useState(1);
  const [outboxLimit, setOutboxLimit] = useState(20);
  const [outboxOnlyFavorites, setOutboxOnlyFavorites] = useState<boolean>(false);

  const [favoritesPage, setFavoritesPage] = useState(1);
  const [favoritesLimit, setFavoritesLimit] = useState(20);

  /** 后端消息列表状态 */
  const [inboxItems, setInboxItems] = useState<IMessage[]>([]);
  const [outboxItems, setOutboxItems] = useState<IMessage[]>([]);
  const [favoriteItems, setFavoriteItems] = useState<IMessage[]>([]);

  /** 将后端数据映射为 UI 结构 Message（保持原渲染逻辑） */
  const inboxMessagesUi = useMemo<Message[]>(() => (inboxItems || []).map(m => ({ id: m.id, from: m.senderId, subject: m.content.slice(0, 32), content: m.content, timestamp: new Date(m.createdAt).toLocaleString(), read: !!m.readAt, type: 'user' })), [inboxItems]);
  const outboxMessagesUi = useMemo<Message[]>(() => (outboxItems || []).map(m => ({ id: m.id, from: '我', subject: m.content.slice(0, 32), content: m.content, timestamp: new Date(m.createdAt).toLocaleString(), read: !!m.readAt, type: 'user' })), [outboxItems]);
  const favoriteMessagesUi = useMemo<Message[]>(() => (favoriteItems || []).map(m => ({ id: m.id, from: m.senderId, subject: m.content.slice(0, 32), content: m.content, timestamp: new Date(m.createdAt).toLocaleString(), read: !!m.readAt, starred: true, type: 'user' })), [favoriteItems]);

  /** 加载各列表 */
  const loadInbox = async () => {
    try {
      const resp = await __request(OpenAPI, { method: 'POST', url: '/messages/inbox', body: { page: inboxPage, limit: inboxLimit, onlyUnread: inboxOnlyUnread, onlyFavorites: inboxOnlyFavorites }, mediaType: 'application/json' });
      const data = unwrapResponse<{ items: IMessage[]; total: number; page: number; limit: number }>(resp);
      setInboxItems(Array.isArray(data?.items) ? data.items : []);
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    }
  };

  const loadOutbox = async () => {
    try {
      const resp = await __request(OpenAPI, { method: 'POST', url: '/messages/outbox', body: { page: outboxPage, limit: outboxLimit, onlyFavorites: outboxOnlyFavorites }, mediaType: 'application/json' });
      const data = unwrapResponse<{ items: IMessage[]; total: number; page: number; limit: number }>(resp);
      setOutboxItems(Array.isArray(data?.items) ? data.items : []);
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    }
  };

  const loadFavorites = async () => {
    try {
      const resp = await __request(OpenAPI, { method: 'POST', url: '/messages/favorites', body: { page: favoritesPage, limit: favoritesLimit }, mediaType: 'application/json' });
      const data = unwrapResponse<{ items: IMessage[]; total: number; page: number; limit: number }>(resp);
      setFavoriteItems(Array.isArray(data?.items) ? data.items : []);
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    }
  };

  useEffect(() => {
    if (activeTab === 'inbox') loadInbox();
    if (activeTab === 'sent') loadOutbox();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab, inboxPage, inboxLimit, inboxOnlyUnread, inboxOnlyFavorites, outboxPage, outboxLimit, outboxOnlyFavorites]);

  useEffect(() => {
    if (activeTab === 'favorites') loadFavorites();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab, favoritesPage, favoritesLimit]);

  /** 会话相关状态 */
  const [threadsPage, setThreadsPage] = useState(1);
  const [threadsLimit, setThreadsLimit] = useState(20);
  const [activeThreadPeerUserId, setActiveThreadPeerUserId] = useState<string | null>(null);
  const [timelinePage, setTimelinePage] = useState(1);
  const [timelineLimit, setTimelineLimit] = useState(50);

  /** 轮询与未读总数 */
  const [lastPollAt, setLastPollAt] = useState<string | null>(null);
  const [unreadTotalCount, setUnreadTotalCount] = useState<number>(0);

  /** 会话摘要与时间线状态 */
  const [threadSummaries, setThreadSummaries] = useState<IThreadSummary[]>([]);
  const [threadMessages, setThreadMessages] = useState<IMessage[]>([]);

  /** 发送新消息表单状态 */
  const [composeRecipientId, setComposeRecipientId] = useState('');
  const [composeSubject, setComposeSubject] = useState('');
  const [composeContent, setComposeContent] = useState('');
  const [composeFormat, setComposeFormat] = useState<'plain' | 'markdown' | 'html'>('plain');
  const [composeAttachments, setComposeAttachments] = useState<string[]>([]);

  /** 回复状态 */
  const [replyContent, setReplyContent] = useState('');
  const [replyFormat, setReplyFormat] = useState<'plain' | 'markdown' | 'html'>('plain');
  const [replyAttachments, setReplyAttachments] = useState<string[]>([]);
  const [replyToMessageId, setReplyToMessageId] = useState<string | null>(null);

  /** 上传图片加入附件 */
  const handleUploadImage = async (file: File, pushTo: 'compose' | 'reply') => {
    try {
      const resp = await __request(OpenAPI, { method: 'POST', url: '/images/upload', formData: { file }, mediaType: 'multipart/form-data' });
      const data = unwrapResponse<{ url: string }>(resp);
      const url = (data as any)?.url;
      if (typeof url === 'string' && url) {
        if (pushTo === 'compose') setComposeAttachments(prev => [...prev, url]);
        else setReplyAttachments(prev => [...prev, url]);
        toast.success('图片上传成功');
      } else {
        toast.error('图片上传失败');
      }
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    }
  };

  /** 发送私信 */
  const sendMessage = async () => {
    try {
      if (!composeRecipientId || !composeContent) {
        toast.error('请填写收件人与内容');
        return;
      }
      const resp = await MessagesService.messagesControllerSend({ recipientId: composeRecipientId, content: composeContent, format: composeFormat, attachments: composeAttachments } as any);
      unwrapResponse(resp);
      toast.success('消息已发送');
      setShowCompose(false);
      setComposeRecipientId('');
      setComposeSubject('');
      setComposeContent('');
      setComposeAttachments([]);
      await loadOutbox();
      await loadThreads();
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    }
  };

  /** 会话回复 */
  const replyMessage = async () => {
    try {
      if (!activeThreadPeerUserId || !replyContent) {
        toast.error('请填写回复内容');
        return;
      }
      const resp = await __request(OpenAPI, { method: 'POST', url: '/messages/reply', body: { peerUserId: activeThreadPeerUserId, replyToMessageId: replyToMessageId || undefined, content: replyContent, format: replyFormat, attachments: replyAttachments }, mediaType: 'application/json' });
      unwrapResponse(resp);
      toast.success('回复已发送');
      setReplyContent('');
      setReplyAttachments([]);
      setReplyToMessageId(null);
      await loadThreadMessages(activeThreadPeerUserId);
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    }
  };

  /** 会话列表与时间线加载 */
  const loadThreads = async () => {
    try {
      const resp = await MessagesService.messagesControllerThreads({ page: threadsPage, limit: threadsLimit });
      const data = unwrapResponse<{ items: IThreadSummary[]; total: number; page: number; limit: number }>(resp);
      setThreadSummaries(Array.isArray(data?.items) ? data.items : []);
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    }
  };

  const loadThreadMessages = async (peerUserId: string) => {
    try {
      const resp = await MessagesService.messagesControllerListMessages({ peerUserId, page: timelinePage, limit: timelineLimit });
      const data = unwrapResponse<{ items: IMessage[]; total: number; page: number; limit: number }>(resp);
      setThreadMessages(Array.isArray(data?.items) ? data.items : []);
      await MessagesService.messagesControllerMarkRead({ peerUserId });
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    }
  };

  useEffect(() => {
    if (activeTab === 'threads') loadThreads();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab, threadsPage, threadsLimit]);

  /** 未读总数与轮询 */
  const refreshUnreadCount = async () => {
    try {
      const resp = await MessagesService.messagesControllerUnreadCount();
      const data = unwrapResponse<{ count: number }>(resp);
      const count = Number((data as any)?.count || 0);
      setUnreadTotalCount(count);
    } catch (_) { }
  };

  useEffect(() => {
    refreshUnreadCount();
    setLastPollAt(new Date().toISOString());
    const timer = setInterval(async () => {
      try {
        const since = lastPollAt || new Date(Date.now() - 5 * 60 * 1000).toISOString();
        const resp = await __request(OpenAPI, { method: 'POST', url: '/messages/poll', body: { since }, mediaType: 'application/json' });
        const data = unwrapResponse<{ inboxNewCount: number; notificationsNewCount: number; threadsUpdated: Array<{ threadId: string; peerUserId: string; lastMessageAt: string; unread: number }> }>(resp);
        setLastPollAt(new Date().toISOString());
        if (Array.isArray((data as any)?.threadsUpdated) && (data as any).threadsUpdated.length > 0) {
          toast.info('有新会话更新');
          await loadThreads();
        }
        await refreshUnreadCount();
      } catch (_) { }
    }, 3 * 60 * 1000);
    return () => clearInterval(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /** 单条消息操作 */
  const favoriteMessage = async (id: string) => {
    try {
      await __request(OpenAPI, { method: 'POST', url: '/messages/favorite', body: { id }, mediaType: 'application/json' });
      toast.success('已收藏');
      if (activeTab === 'inbox') await loadInbox();
      if (activeTab === 'sent') await loadOutbox();
      if (activeTab === 'favorites') await loadFavorites();
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    }
  };

  const unfavoriteMessage = async (id: string) => {
    try {
      await __request(OpenAPI, { method: 'POST', url: '/messages/unfavorite', body: { id }, mediaType: 'application/json' });
      toast.success('已取消收藏');
      if (activeTab === 'inbox') await loadInbox();
      if (activeTab === 'sent') await loadOutbox();
      if (activeTab === 'favorites') await loadFavorites();
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    }
  };

  const markMessageRead = async (id: string) => {
    try {
      await __request(OpenAPI, { method: 'POST', url: '/messages/mark-read', body: { id }, mediaType: 'application/json' });
      toast.success('已标记为已读');
      if (activeTab === 'inbox') await loadInbox();
      if (activeTab === 'sent') await loadOutbox();
      if (activeTab === 'favorites') await loadFavorites();
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    }
  };

  /** 同步 URL 的当前 Tab */
  useEffect(() => {
    const t = searchParams.get('tab');
    if (t && (ALLOWED_TABS as readonly string[]).includes(t)) setActiveTab(t as MessageType);
  }, [searchParams]);

  useEffect(() => {
    setSearchParams(prev => { const p = new URLSearchParams(prev); p.set('tab', activeTab); return p; });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab]);

  /** 搜索防抖 */
  useEffect(() => { const timer = setTimeout(() => setDebouncedQuery(searchQuery), 300); return () => clearTimeout(timer); }, [searchQuery]);

  /** 系统通知列表与操作 */
  const [systemNotifications, setSystemNotifications] = useState<INotification[]>([]);

  const systemMessagesUi = useMemo<Message[]>(() => (systemNotifications || []).map(n => ({ id: n.id, from: '系统通知', subject: n.title, content: n.content, timestamp: new Date(n.createdAt).toLocaleString(), read: !!n.readAt, type: 'system' })), [systemNotifications]);

  const loadSystemNotifications = async () => {
    try {
      const resp = await __request(OpenAPI, { method: 'POST', url: '/messages/notifications/list', body: { page: notificationsPage, limit: notificationsLimit }, mediaType: 'application/json' });
      const data = unwrapResponse<{ items: INotification[]; total: number; page: number; limit: number }>(resp);
      setSystemNotifications(Array.isArray(data?.items) ? data.items : []);
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    }
  };

  useEffect(() => { if (activeTab === 'system') loadSystemNotifications(); /* eslint-disable-next-line */ }, [activeTab, notificationsPage, notificationsLimit]);

  const markNotificationsRead = async (ids: string[]) => {
    try {
      await __request(OpenAPI, { method: 'POST', url: '/messages/notifications/mark-read', body: { ids }, mediaType: 'application/json' });
      toast.success('已标记为已读');
      await loadSystemNotifications();
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    }
  };

  const deleteNotification = async (id: string) => {
    try {
      await __request(OpenAPI, { method: 'POST', url: '/messages/notifications/delete', body: { id }, mediaType: 'application/json' });
      toast.success('通知已删除');
      await loadSystemNotifications();
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    }
  };

  /** 当前列表数据选择与过滤 */
  const getCurrentMessages = () => {
    switch (activeTab) {
      case 'system': return systemMessagesUi;
      case 'inbox': return inboxMessagesUi;
      case 'sent': return outboxMessagesUi;
      case 'favorites': return favoriteMessagesUi;
      default: return [];
    }
  };
  const messages = getCurrentMessages();
  const unreadCount = { system: systemMessagesUi.filter(m => !m.read).length, inbox: inboxMessagesUi.filter(m => !m.read).length };
  const filteredMessages = messages.filter(msg => msg.subject.toLowerCase().includes(debouncedQuery.toLowerCase()) || msg.from.toLowerCase().includes(debouncedQuery.toLowerCase()) || msg.content.toLowerCase().includes(debouncedQuery.toLowerCase()));

  /** 渲染 */
  return (
    <div className="min-h-screen bg-[#0F171E] ">
      <div className="max-w-[1600px] mx-auto px-4 md:px-8 py-8">
        {/* 页面标题区域（保持原样式） */}
        <div className="mb-8">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-amber-500 to-orange-600 flex items-center justify-center shadow-lg shadow-amber-500/30">
                <Mail className="w-5 h-5 text-white" />
              </div>
              <div>
                <h1 className="text-white text-3xl flex items-center gap-2">消息中心 {unreadTotalCount > 0 && (<Badge className="bg-red-500 text-white">{unreadTotalCount}</Badge>)}</h1>
                <p className="text-neutral-400 text-sm mt-1">管理您的系统通知和私人消息</p>
              </div>
            </div>
            <Button onClick={() => setShowCompose(true)} className="bg-gradient-to-r from-amber-500 to-orange-600 hover:from-amber-600 hover:to-orange-700 text-white shadow-lg shadow-amber-500/25">
              <Send className="w-4 h-4 mr-2" />发送消息
            </Button>
          </div>
        </div>

        {/* 导航标签栏 */}
        <div className="bg-neutral-800/40 backdrop-blur-sm rounded-2xl border border-neutral-700/50 shadow-2xl overflow-hidden mb-6">
          <div className="flex items-center justify-between px-6 py-4 border-b border-neutral-700/50">
            <TabBar
              activeTab={activeTab}
              unreadCount={unreadCount}
              onChange={(tab) => { setActiveTab(tab); setSelectedMessage(null); setShowCompose(false); if (tab !== 'threads') setActiveThreadPeerUserId(null); }}
            />
            {/* 快捷操作（保留原 UI，具体功能尚未接入） */}
            <div className="flex items-center gap-2">
              {activeTab === 'system' && (
                <Button
                  variant="ghost"
                  size="sm"
                  className="text-neutral-400 hover:text-white hover:bg-neutral-700/30"
                  onClick={() => {
                    const unreadIds = systemNotifications.filter(n => !n.readAt).map(n => n.id);
                    if (unreadIds.length === 0) toast.info('暂无未读通知'); else markNotificationsRead(unreadIds);
                  }}
                >
                  <Bell className="w-4 h-4 mr-2" />全部已读
                </Button>
              )}
              <Button variant="ghost" size="sm" className="text-neutral-400 hover:text-white hover:bg-neutral-700/30"><Archive className="w-4 h-4 mr-2" />归档</Button>
              <Button variant="ghost" size="sm" className="text-neutral-400 hover:text-white hover:bg-neutral-700/30"><Star className="w-4 h-4 mr-2" />星标</Button>
              <Button variant="ghost" size="sm" className="text-neutral-400 hover:text-white hover:bg-neutral-700/30"><Trash2 className="w-4 h-4 mr-2" />回收站</Button>
            </div>
          </div>
        </div>

        {/* 内容区域 */}
        <div>
          {showCompose ? (
            <ComposeForm
              recipientId={composeRecipientId}
              subject={composeSubject}
              content={composeContent}
              format={composeFormat}
              attachments={composeAttachments}
              onRecipientChange={setComposeRecipientId}
              onSubjectChange={setComposeSubject}
              onContentChange={setComposeContent}
              onFormatChange={(v) => setComposeFormat(v)}
              onUploadImage={(file) => handleUploadImage(file, 'compose')}
              onCancel={() => setShowCompose(false)}
              onSend={sendMessage}
            />
          ) : selectedMessage ? (
            <MessageDetail
              message={selectedMessage}
              activeTab={activeTab}
              onClose={() => setSelectedMessage(null)}
              onMarkMessageRead={markMessageRead}
              onFavoriteMessage={favoriteMessage}
              onUnfavoriteMessage={unfavoriteMessage}
              onDeleteMessage={async (id) => {
                try {
                  await MessagesService.messagesControllerDeleteMessage({ id });
                  toast.success('消息已删除');
                  setSelectedMessage(null);
                  if (activeTab === 'inbox') await loadInbox();
                  if (activeTab === 'sent') await loadOutbox();
                  if (activeTab === 'favorites') await loadFavorites();
                } catch (err: any) {
                  toast.error(extractErrorMessage(err));
                }
              }}
              onMarkNotificationRead={markNotificationsRead}
              onDeleteNotification={deleteNotification}
            />
          ) : (
            <div className="bg-neutral-800/40 backdrop-blur-sm rounded-2xl border border-neutral-700/50 shadow-2xl overflow-hidden">
              {/* 搜索栏 */}
              <SearchBar value={searchQuery} onChange={setSearchQuery} />

              {/* 内容：消息列表或会话视图 */}
              {activeTab === 'threads' ? (
                <ThreadsView
                  activePeerUserId={activeThreadPeerUserId}
                  threadSummaries={threadSummaries}
                  threadMessages={threadMessages}
                  replyContent={replyContent}
                  replyFormat={replyFormat}
                  replyAttachments={replyAttachments}
                  replyToMessageId={replyToMessageId}
                  onBackToList={() => { setActiveThreadPeerUserId(null); setThreadMessages([]); }}
                  onSelectThread={(peer) => setActiveThreadPeerUserId(peer)}
                  onLoadThreadMessages={loadThreadMessages}
                  onSetReplyToMessageId={setReplyToMessageId}
                  onReplyContentChange={setReplyContent}
                  onReplyFormatChange={setReplyFormat}
                  onUploadImage={(file) => handleUploadImage(file, 'reply')}
                  onClearReply={() => { setReplyContent(''); setReplyAttachments([]); setReplyToMessageId(null); }}
                  onSendReply={replyMessage}
                />
              ) : (
                <MessageList messages={filteredMessages} onSelect={(msg) => setSelectedMessage(msg)} />
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

