import { useState } from 'react';
import { RequestsHall } from '@/pages/requests/RequestsHall';
import { MyRequests } from '@/pages/requests/MyRequests';
import { MyResponses } from '@/pages/requests/MyResponses';
import { ModerationCenter } from '@/pages/requests/ModerationCenter';
import { CreateRequest } from '@/pages/requests/CreateRequest';
import { Bell, Award, CheckCircle, Shield, PlusCircle } from 'lucide-react';

type TabView = 'hall' | 'my-requests' | 'my-responses' | 'moderation' | 'create';

export function RequestsPage() {
  const [activeTab, setActiveTab] = useState<TabView>('hall');
  const [isAdmin] = useState(true); // 模拟管理员身份

  const tabs = [
    { id: 'hall' as TabView, label: '求种大厅', icon: Bell, adminOnly: false },
    { id: 'my-requests' as TabView, label: '我的求种', icon: Award, adminOnly: false },
    { id: 'my-responses' as TabView, label: '我的应答', icon: CheckCircle, adminOnly: false },
    { id: 'moderation' as TabView, label: '仲裁中心', icon: Shield, adminOnly: true },
    { id: 'create' as TabView, label: '发布求种', icon: PlusCircle, adminOnly: false },
  ];

  const visibleTabs = tabs.filter(tab => !tab.adminOnly || isAdmin);

  const renderContent = () => {
    switch (activeTab) {
      case 'hall':
        return <RequestsHall />;
      case 'my-requests':
        return <MyRequests />;
      case 'my-responses':
        return <MyResponses />;
      case 'moderation':
        return <ModerationCenter />;
      case 'create':
        return <CreateRequest />;
      default:
        return <RequestsHall />;
    }
  };

  return (
    <div className="min-h-screen bg-[#0F171E] pt-16">
      {/* Header with gradient */}
      <div className="bg-gradient-to-br from-amber-600/20 via-orange-600/20 to-amber-700/20 border-b border-amber-500/20">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          <h1 className="text-amber-50 mb-2">求种中心</h1>
          <p className="text-amber-200/70">发布您的资源需求，让社区帮您实现</p>
        </div>
      </div>

      {/* Fixed Tab Navigation */}
      <div className="sticky top-16 z-40 bg-[#0F171E]/95 backdrop-blur-sm border-b border-amber-500/20">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex gap-1 overflow-x-auto">
            {visibleTabs.map((tab) => {
              const Icon = tab.icon;
              const isActive = activeTab === tab.id;

              return (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`
                    flex items-center gap-2 px-6 py-4 whitespace-nowrap transition-all duration-200
                    ${isActive
                      ? 'text-amber-400 border-b-2 border-amber-400 bg-gradient-to-br from-amber-600/10 to-orange-600/10'
                      : 'text-amber-200/60 hover:text-amber-300 hover:bg-amber-500/5'
                    }
                  `}
                >
                  <Icon className="w-4 h-4" />
                  <span>{tab.label}</span>
                  {tab.adminOnly && (
                    <Shield className="w-3 h-3 text-orange-400" />
                  )}
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* Content Area */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {renderContent()}
      </div>
    </div>
  );
}